/**
 圆的显示范围
 uv 
 p 坐标
 r 半径
 blur 模糊
*/
float Circle(vec2 uv,vec2 p,float r,float blur){
     float d=length(uv-p);
     float c=smoothstep(r,r-0.01,d);
     return c;
}

float Smiley(vec2 uv,vec2 p,float size){
    uv-=p;
    uv/=size;
    float mask=.0;
    float c=Circle(uv,vec2(0.,.0),0.4,.01);

    c-=Circle(uv,vec2(-.13,.2),0.07,.01);  //left eye
    c-=Circle(uv,vec2(.13,.2),0.07,.01);   //right eye

    mask+=c;

    float mouth=Circle(uv,vec2(.0,.0),.3,.02);
    mouth-=Circle(uv,vec2(.0,.1),.3,.02);

    mask-=mouth;
    return mask;
}

float Band(float t,float start,float end,float blur){
    float step_1=smoothstep(start-blur,start+blur,t);
    float step_2=smoothstep(end+blur,end-blur,t);

    return step_1*step_2;
}

float Rect(vec2 uv,float start,float end,float bottom,float top,float blur){
    float band_1=Band(uv.x,start,end,blur);   
    float band_2=Band(uv.y,bottom,top,blur);   
    return band_1*band_2;
}

float remap01(float a,float b,float t){
    return (t-a)/(b-a);
}

float remap(float a,float b,float c,float d,float t){
    return remap01(a,b,t)*(d-c);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;   // [0,1]
    float t= iTime;

    uv-=.5;
    uv.x*=iResolution.x/iResolution.y;   // x转换成y一样的宽高

    vec2 pos=vec2(uv);
    float m=-(uv.x-.5)*(uv.x+.5);
    //m=m*m*4.;
    m=sin(t+uv.x*8.)*.1;
    pos.y-=m;
    float blur=remap(-.5,.5,.01,.25,uv.x);
    float mask=Rect(pos,-0.5,0.5,-0.1,0.1,blur);

    vec3 col=vec3(1.,1.,1.)*mask;
    fragColor = vec4(col,1.0);
}
